		System.out.println("3.14");
		System.out.println('A');
		System.out.println("");
		
		System.out.println("");
		System.out.println(3+5);
		System.out.println(3.9+5.72);
		System.out.println(3.9*5.72);
		System.out.println(10/3);
		//정수 나눗셈의 결과는 몫을 나타낸다.
		System.out.println(7/3.0);
